    {
      "id": "why-pea",
      "kind": "content",
      "eyebrow": "历史与实验",
      "headline": "为什么选择豌豆？",
      "lead": "孟德尔巧妙的选择使遗传规律得以显现。",
      "notes": "孟德尔在 1856-1863 年进行了长达 8 年的豌豆杂交实验。他选择豌豆是因为：豌豆是自花传粉、闭花授粉植物，自然状态下保持纯种；具有 7 对稳定可区分的相对性状，如高茎与矮茎（成熟植株高度）、圆粒与皱粒（种子形状）等；花大易于人工去雄和授粉；子代数量多，便于统计分析。这些特点使豌豆成为遗传学研究的理想材料。",
      "blocks": [
        {
          "id": "b_pea_reasons",
          "type": "list",
          "intent": "列举孟德尔选择豌豆的四个主要原因：自花传粉纯种、稳定相对性状、易操作、子代多。"
        }
      ]
    },
    {
      "id": "monohybrid",
      "kind": "content",
      "eyebrow": "分离定律",
      "headline": "单因子杂交实验",
      "lead": "一对相对性状的杂交揭示了遗传因子的分离。",
      "notes": "孟德尔将纯种高茎豌豆与纯种矮茎豌豆杂交，F1 代全部为高茎。他让 F1 自交，F2 代出现高茎和矮茎，比例约为 3:1。他提出假设：遗传因子成对存在，显性因子（D）和隐性因子（d）；形成配子时成对因子分离，每个配子只含一个因子；受精时雌雄配子随机结合。F1 基因型 Dd，产生 D 和 d 配子各一半，随机结合得到 DD:Dd:dd=1:2:1，表型高茎:矮茎=3:1。这就是分离定律。",
      "blocks": [
        {
          "id": "b_monohybrid_flow",
          "type": "flow",
          "intent": "展示单因子杂交实验流程：P 高茎×矮茎 → F1 全高茎 → F2 3:1"
        },
        {
          "id": "b_segregation_law",
          "type": "callout",
          "intent": "强调分离定律核心：配子形成时等位基因分离"
        }
      ]
    },
    {
      "id": "probability-segregation",
      "kind": "content",
      "eyebrow": "概率与统计",
      "headline": "3:1 背后的概率",
      "lead": "配子随机结合是分离比成立的数学前提。",
      "notes": "分离定律的 3:1 比例本质上是概率问题。杂合子 Dd 产生 D 和 d 配子的概率均为 1/2。雌雄配子随机结合，相当于两个独立事件同时发生。后代基因型概率：DD=1/2×1/2=1/4，Dd=1/2×1/2+1/2×1/2=1/2，dd=1/2×1/2=1/4。表型显性概率=1/4+1/2=3/4，隐性=1/4。乘法法则用于两个独立事件同时发生，加法法则用于互斥事件（如 Dd 有两种组合方式）。",
      "blocks": [
        {
          "id": "b_punnett",
          "type": "grid",
          "intent": "用 Punnett 方格展示 Dd×Dd 的配子组合和后代基因型"
        },
        {
          "id": "b_prob_formula",
          "type": "formula",
          "intent": "给出概率计算公式：P(DD)=1/4, P(Dd)=1/2, P(dd)=1/4"
        }
      ]
    },
    {
      "id": "dihybrid",
      "kind": "content",
      "eyebrow": "自由组合定律",
      "headline": "双因子杂交实验",
      "lead": "两对相对性状的杂交揭示了遗传因子的自由组合。",
      "notes": "孟德尔接着研究两对相对性状：种子颜色（黄/绿）和形状（圆/皱）。纯种黄色圆粒与绿色皱粒杂交，F1 全为黄色圆粒（显性）。F1 自交，F2 出现四种表型：黄色圆粒、黄色皱粒、绿色圆粒、绿色皱粒，比例 9:3:3:1。他提出：不同性状的遗传因子在形成配子时自由组合。即 YyRr 产生 YR、Yr、yR、yr 四种配子，比例 1:1:1:1，随机结合得到 16 种组合，表型比例 9:3:3:1。",
      "blocks": [
        {
          "id": "b_dihybrid_flow",
          "type": "flow",
          "intent": "展示双因子杂交实验流程：P 黄圆×绿皱 → F1 全黄圆 → F2 9:3:3:1"
        },
        {
          "id": "b_freecomb_law",
          "type": "callout",
          "intent": "强调自由组合定律：非同源染色体上的非等位基因自由组合"
        }
      ]
    },
    {
      "id": "probability-dihybrid",
      "kind": "content",
      "eyebrow": "概率与统计",
      "headline": "9:3:3:1 的概率推导",
      "lead": "两对独立遗传的性状，表型比例等于各自分离比的乘积。",
      "notes": "9:3:3:1 比例可以分解为两个 3:1 的乘积。先看颜色：黄色:绿色=3:1；再看形状：圆粒:皱粒=3:1。由于两对基因独立遗传，所以黄色圆粒=3/4×3/4=9/16，黄色皱粒=3/4×1/4=3/16，绿色圆粒=1/4×3/4=3/16，绿色皱粒=1/4×1/4=1/16。这种分解方法适用于任何多对独立遗传的性状。",
      "blocks": [
        {
          "id": "b_prob_dihybrid_formula",
          "type": "formula",
          "intent": "给出 9:3:3:1 的概率计算：各性状独立，比例相乘"
        },
        {
          "id": "b_prob_dihybrid_steps",
          "type": "agenda",
          "intent": "逐步推导：先分性状计算比例，再相乘得到最终比例"
        }
      ]
    },
    {
      "id": "testcross",
      "kind": "content",
      "eyebrow": "实验验证",
      "headline": "测交：检验定律的试金石",
      "lead": "与隐性纯合子杂交，可以推断待测个体的基因型。",
      "notes": "测交是孟德尔验证假设的关键实验。他用 F1 杂合子与隐性纯合子杂交。对于一对基因：Dd×dd，后代高茎:矮茎≈1:1，证明 F1 产生两种配子且比例相等。对于两对基因：YyRr×yyrr，后代四种表型比例 1:1:1:1，证明 F1 产生四种等比例配子。测交不仅能验证定律，还能检测未知个体的基因型，是遗传学的基本工具。",
      "blocks": [
        {
          "id": "b_testcross_flow",
          "type": "flow",
          "intent": "展示测交实验：F1 与隐性纯合子杂交，预期比例"
        },
        {
          "id": "b_testcross_significance",
          "type": "statement",
          "intent": "说明测交是验证基因型的有效方法"
        }
      ]
    },
    {
      "id": "cytological-basis",
      "kind": "content",
      "eyebrow": "细胞学视角",
      "headline": "染色体行为与遗传定律",
      "lead": "减数分裂中染色体的行为完美解释了孟德尔定律。",
      "notes": "20 世纪初，科学家发现染色体与遗传因子的平行关系。减数分裂中：同源染色体在减数第一次分裂后期分离，导致等位基因分离（分离定律的细胞学本质）。非同源染色体在减数第一次分裂后期随机分配到两极，导致非等位基因自由组合（自由组合定律的细胞学本质）。因此，孟德尔定律实质上是染色体行为的反映。",
      "blocks": [
        {
          "id": "b_meiosis_flow",
          "type": "flow",
          "intent": "展示减数分裂中同源染色体分离和非同源染色体自由组合"
        },
        {
          "id": "b_cytological_summary",
          "type": "statement",
          "intent": "总结：分离定律=同源染色体分离，自由组合定律=非同源染色体自由组合"
        }
      ]
    },
    {
      "id": "linkage",
      "kind": "content",
      "eyebrow": "例外与扩展",
      "headline": "连锁与交换：自由组合的例外",
      "lead": "位于同一染色体上的基因倾向于一起遗传。",
      "notes": "摩尔根用果蝇实验发现连锁遗传：位于同一染色体上的基因不遵循自由组合，而是倾向于一起遗传。但同源染色体上的非姐妹染色单体在减数第一次分裂前期发生交叉互换，可以产生重组配子。交换率（重组率）与基因在染色体上的距离成正比，因此可用于遗传作图。连锁与交换是自由组合定律的重要补充。",
      "blocks": [
        {
          "id": "b_linkage_flow",
          "type": "flow",
          "intent": "展示同源染色体交叉互换导致基因重组"
        },
        {
          "id": "b_linkage_statement",
          "type": "statement",
          "intent": "说明连锁遗传和交换率的概念"
        }
      ]
    },
    {
      "id": "special-cases",
      "kind": "content",
      "eyebrow": "应用与拓展",
      "headline": "不完全显性、共显性与伴性遗传",
      "lead": "孟德尔定律在更多遗传现象中展现其适用性与边界。",
      "notes": "孟德尔定律在更多遗传现象中展现其适用性。不完全显性：如金鱼草花色，RR 红花×rr 白花→Rr 粉花，F2 比例 1:2:1。共显性：如 ABO 血型，IA 和 IB 等位基因同时表达，产生 AB 型。伴性遗传：如人类红绿色盲，基因位于 X 染色体，男性（XY）只要一个隐性等位基因就患病，女性（XX）需要两个。伴 X 显性遗传则女性发病率更高。",
      "blocks": [
        {
          "id": "b_dominance_compare",
          "type": "compare",
          "intent": "对比完全显性、不完全显性、共显性的表型比例"
        },
        {
          "id": "b_sexlinked_table",
          "type": "table",
          "intent": "比较伴 X 显性、伴 X 隐性、伴 Y 遗传的特点"
        }
      ]
    },
    {
      "id": "pedigree-quiz",
      "kind": "quiz",
      "headline": "随堂检验：系谱图分析",
      "notes": "给出一个系谱图，判断遗传方式并计算概率。例如：常染色体隐性遗传病（如白化病）的系谱，两个表型正常的夫妇生了一个患病孩子，问他们再生孩子患病的概率？或者伴 X 隐性遗传（如色盲）的系谱，判断基因型并计算概率。注意条件概率：已知孩子正常，问是携带者的概率？",
      "blocks": [
        {
          "id": "b_quiz",
          "type": "quiz",
          "intent": "考察学生运用遗传定律分析系谱图和计算概率的能力"
        }
      ]
    },
    {
      "id": "summary",
      "kind": "hero",
      "notes": "孟德尔遗传定律是遗传学的基础。分离定律：等位基因在配子形成时分离。自由组合定律：非同源染色体上的非等位基因自由组合。它们的细胞学基础是减数分裂中的染色体行为。概率论为遗传分析提供了数学工具。这些定律适用于有性生殖的真核生物，但存在连锁、不完全显性等例外。理解这些定律，是学习现代遗传学的起点。",
      "blocks": [
        {
          "id": "b_summary",
          "type": "hero",
          "intent": "收尾：总结两大定律，强调科学探究精神"
        }
      ]
    }
  ]
